let particles = [];
let R;
let maxR;
let t = 0;
let nt = 0;
let nR = 0;
let nTheta = 1000;
let colors = [];


function setup() {

    createCanvas(windowWidth, windowHeight);
    colorMode(HSB, 360, 100, 100, 100);
    pixelDensity(5);
    angleMode(DEGREES);
    noStroke();
    maxR = max(width, height) * 0.55;
    background(0, 0, 95, 100);

}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

    colors[0] = color(300, 40, 90, random(1, 3));
    colors[1] = color(300, 60, 90, random(1, 5));
    colors[2] = color(320, 10, 95, random(1, 2));
    colors[3] = color(340, 40, 85, random(1, 5));

    var R = map(noise(nt * 0.01, nR), 0, 1, 0, maxR);
    var t = map(noise(nt * 0.001, nTheta), 0, 1, -360, 360);
    let x = R * cos(t) + width / 2;
    let y = R * sin(t) + height / 2;
    let p = new Particle(x, y);
    particles.push(p);

    if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
        particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
    }

    for (let j = particles.length - 1; j > 0; j--) {
        particles[j].show();
        particles[j].update();
        if (particles[j].finished()) {
            particles.splice(j, 1);
        }
    }
    nt++;
}


// === Tab: tab4.js ===
function Particle(x, y) {
    this.x = x;
    this.y = y;
    this.vel = createVector(0, 0);
    this.pos = createVector(this.x, this.y);
    this.noiseScale = 0.005;
    this.t = random(0, this.noiseScale);
    this.lifeMax = random(120, 50);
    this.life = this.lifeMax;
    this.step = random(0.1, 0.5);
    this.dMax = random(10) >= 5 ? 10 : 50;
    this.d = this.dMax;
    this.c = color(random(colors));

    this.update = function() {
        let theta = map(noise(this.pos.x * this.noiseScale, this.pos.y * this.noiseScale, this.t), 0, 1, -360, 360);
        this.vel.x = cos(theta);
        this.vel.y = sin(theta);
        this.pos.add(this.vel);
    };

    this.show = function() {
        stroke(this.c);
        strokeWeight(0.25); 
        line(this.pos.x, this.pos.y, width / 2, height / 2);
    };

    this.finished = function() {
        this.life -= this.step;
        this.d = map(this.life, 0, this.lifeMax, 0, this.dMax);
        if (this.life < 0) {
            return true;
        } else {
            return false;
        }
    };
}

